mapper.update:
UPDATE line_after_sales SET status=#{to},decision=#{decision},received_quantity=#{receivedQuantity},
  next_attempt_at=CURRENT_TIMESTAMP(6),updated_at=CURRENT_TIMESTAMP(6)
WHERE id=#{id} AND merchant_id=#{merchantId} AND status=#{from}

UPDATE line_after_sales SET status=#{to},refund_number=COALESCE(#{refundNumber},refund_number),
  last_error=NULL,next_attempt_at=CURRENT_TIMESTAMP(6),updated_at=CURRENT_TIMESTAMP(6)
WHERE id=#{id} AND status=#{from}

UPDATE line_after_sales SET last_error=#{error},
  next_attempt_at=TIMESTAMPADD(SECOND, 5, CURRENT_TIMESTAMP(6)),updated_at=CURRENT_TIMESTAMP(6)
WHERE id=#{id} AND status=#{status}
